    # The structures are 3x3 blocks.

    # First, let's identify the current positions of the structures.
    # We look for 3x3 blocks that match the pattern of the structures.

    # Pattern for structure 5 (gray):
    # 5 5 5
    # 5 0 5
    # 5 5 5
    # But from observations, it seems more complex. Let's look at the diffs.

    # Actually, looking at the diffs, the structures are 3x3 blocks that move together.
    # Let's find the top-left corner of each structure.

    # We'll search for 3x3 blocks that contain colors 4 or 5 and 0.

    structures = []

    for r in range(62):
        for c in range(62):
            # Check if this is the top-left of a 3x3 structure
            block = []
            for dr in range(3):
                for dc in range(3):
                    block.append(new_grid[r+dr][c+dc])

            # Check if this block is a structure (contains 4 or 5 and 0)
            if 4 in block or 5 in block:
                # Check if it's a valid structure pattern
                # Structure 5 pattern:
                # 5 5 5
                # 5 0 5
                # 5 5 5
                # Structure 4 pattern:
                # 4 4 4
                # 4 0 4
                # 4 4 4
                # But from observations, the patterns are more complex.

                # Let's just check if the block contains the structure colors
                if 5 in block and 0 in block:
                    structures.append((r, c, 5))
                elif 4 in block and 0 in block:
                    structures.append((r, c, 4))

    # Remove duplicate structures (keep only unique top-left corners)
    unique_structures = []
    seen = set()
    for s in structures:
        if s[:2] not in seen:
            unique_structures.append(s)
            seen.add(s[:2])

    # Now, apply the action
    if action == 1:  # UP
        for r, c, color in unique_structures:
            # Move the structure up by 1
            if r > 0:
                # Clear the old position
