                    for dc in range(3):
                        old_val = grid[r+dr][c+dc]
                        if old_val in [4, 5, 0]:
                            new_grid[r-1+dr][c+dc] = old_val
                        else:
                            new_grid[r-1+dr][c+dc] = 9

    elif action == 2:  # RIGHT
        for r, c, color in unique_structures:
            # Move the structure right by 1
            if c < 61:
                # Clear the old position
                for dr in range(3):
                    for dc in range(3):
                        if new_grid[r+dr][c+dc] in [4, 5, 0]:
                            new_grid[r+dr][c+dc] = 9
                # Place the structure at the new position
                for dr in range(3):
                    for dc in range(3):
                        old_val = grid[r+dr][c+dc]
                        if old_val in [4, 5, 0]:
                            new_grid[r+dr][c+1+dc] = old_val
                        else:
                            new_grid[r+dr][c+1+dc] = 9

    elif action == 3:  # LEFT
        for r, c, color in unique_structures:
            # Move the structure left by 1
            if c > 0:
                # Clear the old position
                for dr in range(3):
                    for dc in range(3):
                        if new_grid[r+dr][c+dc] in [4, 5, 0]:
                            new_grid[r+dr][c+dc] = 9
                # Place the structure at the new position
