                        if old_val in [4, 5, 0]:
                            new_grid[r+dr][c-1+dc] = old_val
                        else:
                            new_grid[r+dr][c-1+dc] = 9

    elif action == 4:  # DOWN
        for r, c, color in unique_structures:
            # Move the structure down by 1
            if r < 61:
                # Clear the old position
                for dr in range(3):
                    for dc in range(3):
                        if new_grid[r+dr][c+dc] in [4, 5, 0]:
                            new_grid[r+dr][c+dc] = 9
                # Place the structure at the new position
                for dr in range(3):
                    for dc in range(3):
                        old_val = grid[r+dr][c+dc]
                        if old_val in [4, 5, 0]:
                            new_grid[r+1+dr][c+dc] = old_val
                        else:
                            new_grid[r+1+dr][c+dc] = 9

    elif action == 5:  # Increment counter
        # Find the counter cell (bottom-right area)
        # From observations, the counter is at (63, y) where y increases
        # Let's find the rightmost column with non-background cells
        for r in range(63, -1, -1):
            if new_grid[r][63] != 9 and new_grid[r][63] != -1:
                # Increment the counter
