                    new_grid[r][63] = 5
                else:
                    new_grid[r][63] = 5
                break

    elif action == 7:  # Undo/Reset
        # This action seems to reset the structures to their initial positions
        # For simplicity, we'll just return the original grid
        new_grid = copy.deepcopy(grid)

    return new_grid

